from pathlib import Path

ROOT = Path.cwd()

def write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text.strip() + "\n", encoding="utf-8")

def main() -> None:
    write(ROOT / "scripts" / "build-cpn-report-from-nunitxml.py", 'from __future__ import annotations\n\nimport argparse\nimport html\nimport json\nimport os\nimport re\nimport xml.etree.ElementTree as ET\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\n\ndef status_from(result: str | None, label: str | None) -> str:\n    result = result or ""\n    label = label or ""\n\n    if result in {"Passed", "Failed", "Skipped", "Inconclusive", "Warning"}:\n        return result\n\n    if re.search(r"Ignored|Explicit|Cancelled|Skipped", label, re.I):\n        return "Skipped"\n\n    return "Unknown"\n\n\ndef fixture_name(full_name: str) -> str:\n    if "." not in full_name:\n        return full_name\n    return full_name.rsplit(".", 1)[0]\n\n\ndef read_message(node: ET.Element) -> tuple[str, str]:\n    message = ""\n    stack_trace = ""\n\n    failure = node.find("failure")\n    reason = node.find("reason")\n\n    if failure is not None:\n        message_node = failure.find("message")\n        stack_node = failure.find("stack-trace")\n        if message_node is not None and message_node.text:\n            message = message_node.text\n        if stack_node is not None and stack_node.text:\n            stack_trace = stack_node.text\n\n    if not message and reason is not None:\n        message_node = reason.find("message")\n        if message_node is not None and message_node.text:\n            message = message_node.text\n\n    return message, stack_trace\n\n\ndef categories(node: ET.Element) -> list[str]:\n    values: list[str] = []\n    properties = node.find("properties")\n    if properties is None:\n        return values\n\n    for prop in properties.findall("property"):\n        if prop.attrib.get("name") == "Category":\n            value = prop.attrib.get("value")\n            if value:\n                values.append(value)\n\n    return sorted(set(values), key=str.lower)\n\n\ndef parse_nunit_xml(xml_root: Path) -> list[dict]:\n    tests: list[dict] = []\n\n    for path in sorted(xml_root.rglob("*.xml")):\n        try:\n            tree = ET.parse(path)\n        except ET.ParseError:\n            continue\n\n        root = tree.getroot()\n\n        for node in root.findall(".//test-case"):\n            name = node.attrib.get("name", "")\n            full_name = node.attrib.get("fullname") or name\n            result = node.attrib.get("result")\n            label = node.attrib.get("label")\n            status = status_from(result, label)\n            duration_seconds = 0.0\n\n            try:\n                duration_seconds = float(node.attrib.get("duration", "0") or "0")\n            except ValueError:\n                duration_seconds = 0.0\n\n            message, stack_trace = read_message(node)\n\n            tests.append({\n                "id": f"{len(tests) + 1:06d}",\n                "testName": name,\n                "fullName": full_name,\n                "fixtureName": fixture_name(full_name),\n                "status": status,\n                "durationMilliseconds": round(duration_seconds * 1000, 2),\n                "message": message,\n                "stackTrace": stack_trace,\n                "categories": categories(node),\n                "sourceXml": str(path),\n            })\n\n    return tests\n\n\ndef write_report(tests: list[dict], output_root: Path, framework_name: str) -> None:\n    output_root.mkdir(parents=True, exist_ok=True)\n    tests_root = output_root / "Tests"\n    tests_root.mkdir(parents=True, exist_ok=True)\n\n    total = len(tests)\n    passed = sum(1 for item in tests if item["status"] == "Passed")\n    failed = sum(1 for item in tests if item["status"] == "Failed")\n    skipped = sum(1 for item in tests if item["status"] == "Skipped")\n    other = total - passed - failed - skipped\n\n    summary = {\n        "framework": framework_name,\n        "source": "NUnitXml",\n        "generatedUtc": datetime.now(timezone.utc).isoformat(),\n        "total": total,\n        "passed": passed,\n        "failed": failed,\n        "skipped": skipped,\n        "other": other,\n        "tests": tests,\n    }\n\n    (output_root / "cpn-report.json").write_text(\n        json.dumps(summary, indent=2),\n        encoding="utf-8",\n    )\n    (output_root / "cpn-report-all-tests.json").write_text(\n        json.dumps(summary, indent=2),\n        encoding="utf-8",\n    )\n\n    for item in tests:\n        safe = re.sub(r\'[\\\\/:*?"<>|]\', "_", item["fullName"])[:150]\n        (tests_root / f"{safe}.json").write_text(\n            json.dumps(item, indent=2),\n            encoding="utf-8",\n        )\n\n    rows = []\n    for item in sorted(tests, key=lambda value: (value["status"], value["fullName"])):\n        message = html.escape(item.get("message") or "")\n        stack_trace = item.get("stackTrace") or ""\n        if stack_trace:\n            message += (\n                "<details><summary>Stack trace</summary><pre>"\n                + html.escape(stack_trace)\n                + "</pre></details>"\n            )\n\n        rows.append(\n            "<tr>"\n            f"<td class=\\"{html.escape(item[\'status\'])}\\">{html.escape(item[\'status\'])}</td>"\n            f"<td><code>{html.escape(item[\'fullName\'])}</code></td>"\n            f"<td>{html.escape(str(item[\'durationMilliseconds\']))} ms</td>"\n            f"<td>{message}</td>"\n            "</tr>"\n        )\n\n    html_report = f"""<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1" />\n<title>CPN Full Test Report</title>\n<style>\nbody{{font-family:Segoe UI,Arial,sans-serif;margin:24px;background:#f7f7f8;color:#1f2328;}}\nh1{{margin-bottom:4px;}}\n.meta{{color:#57606a;margin-bottom:18px;}}\n.cards{{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:24px;}}\n.card{{background:white;border:1px solid #d0d7de;border-radius:8px;padding:14px 22px;min-width:120px;}}\n.number{{font-size:30px;font-weight:700;}}\ntable{{width:100%;border-collapse:collapse;background:white;border:1px solid #d0d7de;}}\nth,td{{text-align:left;border-bottom:1px solid #d8dee4;padding:10px;vertical-align:top;}}\nth{{background:#f1f3f5;}}\n.Passed{{color:#1a7f37;font-weight:700;}}\n.Failed{{color:#cf222e;font-weight:700;}}\n.Skipped,.Inconclusive,.Warning,.Unknown{{color:#9a6700;font-weight:700;}}\ncode{{font-family:Consolas,monospace;font-size:12px;}}\npre{{white-space:pre-wrap;}}\n</style>\n</head>\n<body>\n<h1>CPN Full Test Report</h1>\n<div class="meta">Framework: {html.escape(framework_name)} | Source: NUnit XML | Generated UTC: {html.escape(summary["generatedUtc"])}</div>\n<div class="cards">\n  <div class="card"><div class="number">{total}</div><div>Total</div></div>\n  <div class="card"><div class="number">{passed}</div><div>Passed</div></div>\n  <div class="card"><div class="number">{failed}</div><div>Failed</div></div>\n  <div class="card"><div class="number">{skipped}</div><div>Skipped</div></div>\n  <div class="card"><div class="number">{other}</div><div>Other</div></div>\n</div>\n<table>\n<thead><tr><th>Status</th><th>Test</th><th>Duration</th><th>Message</th></tr></thead>\n<tbody>\n{os.linesep.join(rows)}\n</tbody>\n</table>\n</body>\n</html>\n"""\n\n    (output_root / "cpn-report.html").write_text(html_report, encoding="utf-8")\n    (output_root / "cpn-report-all-tests.html").write_text(html_report, encoding="utf-8")\n\n    (output_root / "cpn-report-summary.txt").write_text(\n        (\n            f"Framework: {framework_name}\\n"\n            f"Source: NUnitXml\\n"\n            f"Total: {total}\\n"\n            f"Passed: {passed}\\n"\n            f"Failed: {failed}\\n"\n            f"Skipped: {skipped}\\n"\n            f"Other: {other}\\n"\n        ),\n        encoding="utf-8",\n    )\n\n    print(f"Created {output_root / \'cpn-report.html\'}")\n    print(f"Total: {total} Passed: {passed} Failed: {failed} Skipped: {skipped} Other: {other}")\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--nunit-xml-root", required=True)\n    parser.add_argument("--output-root", required=True)\n    parser.add_argument("--framework-name", default="CVIS.Automation.Tests")\n    parser.add_argument("--minimum-total", type=int, default=1)\n    args = parser.parse_args()\n\n    xml_root = Path(args.nunit_xml_root)\n    output_root = Path(args.output_root)\n\n    if not xml_root.exists():\n        raise SystemExit(f"NUnit XML folder does not exist: {xml_root}")\n\n    tests = parse_nunit_xml(xml_root)\n\n    if len(tests) < args.minimum_total:\n        raise SystemExit(\n            f"NUnit XML only contained {len(tests)} tests, expected at least {args.minimum_total}."\n        )\n\n    write_report(tests, output_root, args.framework_name)\n\n\nif __name__ == "__main__":\n    main()\n')
    write(ROOT / "scripts" / "run-all-nunit-reporting-local.ps1", 'param(\n    [string]$Configuration = "Debug",\n    [int]$MinimumTotal = 250\n)\n\n$ErrorActionPreference = "Stop"\n\n$Root = Split-Path -Parent $PSScriptRoot\n$TestResults = Join-Path $Root "TestResults"\n$CpnResults = Join-Path $TestResults "CPN"\n$NUnitResults = Join-Path $TestResults "NUnit"\n$NUnitXmlResults = Join-Path $TestResults "NUnitXml"\n\nif (Test-Path $TestResults) {\n    Remove-Item $TestResults -Recurse -Force\n}\n\nNew-Item -ItemType Directory -Force -Path $CpnResults | Out-Null\nNew-Item -ItemType Directory -Force -Path $NUnitResults | Out-Null\nNew-Item -ItemType Directory -Force -Path $NUnitXmlResults | Out-Null\n\n$env:CPN_REPORT_ENABLED = "true"\n$env:CPN_REPORT_ROOT = $CpnResults\n\n$Projects = @(\n    "$Root\\CVIS.Automation.Tests\\CVIS.Automation.Tests.csproj",\n    "$Root\\CVIS.Playwright.NUnitCompat.Tests\\CVIS.Playwright.NUnitCompat.Tests.csproj"\n)\n\nforeach ($Project in $Projects) {\n    if (-not (Test-Path $Project)) {\n        Write-Host "Skipping missing test project: $Project"\n        continue\n    }\n\n    $ProjectName = [System.IO.Path]::GetFileNameWithoutExtension($Project)\n    $ProjectNUnitResults = Join-Path $NUnitResults $ProjectName\n    $ProjectNUnitXmlResults = Join-Path $NUnitXmlResults $ProjectName\n\n    New-Item -ItemType Directory -Force -Path $ProjectNUnitResults | Out-Null\n    New-Item -ItemType Directory -Force -Path $ProjectNUnitXmlResults | Out-Null\n\n    Write-Host ""\n    Write-Host "Running $ProjectName"\n\n    dotnet test $Project `\n        --configuration $Configuration `\n        --logger "trx;LogFileName=$ProjectName.trx" `\n        --results-directory "$ProjectNUnitResults" `\n        -- NUnit.TestOutputXml="$ProjectNUnitXmlResults"\n}\n\npython "$Root\\scripts\\build-cpn-report-from-nunitxml.py" `\n    --nunit-xml-root "$NUnitXmlResults" `\n    --output-root "$CpnResults" `\n    --framework-name "CVIS Full NUnit Run" `\n    --minimum-total $MinimumTotal\n\nWrite-Host ""\nWrite-Host "AUTHORITATIVE HYPEREXECUTE INPUT:"\nWrite-Host "  $NUnitXmlResults"\nWrite-Host ""\nWrite-Host "FULL CPN HTML REPORT:"\nWrite-Host "  $CpnResults\\cpn-report.html"\nWrite-Host ""\nWrite-Host "SUMMARY:"\nGet-Content (Join-Path $CpnResults "cpn-report-summary.txt")\n')
    write(ROOT / "hyperexecute-authoritative-nunit-reporting.yaml", 'version: "0.1"\nrunson: win\n\nautosplit: false\nconcurrency: 1\ntestRunnerExecutor: cmd\nworkingDirectory: .\n\nenv:\n  CPN_REPORT_ENABLED: "true"\n  CPN_REPORT_ROOT: ".\\TestResults\\CPN"\n\npre:\n  - if exist .\\TestResults rmdir /s /q .\\TestResults\n  - dotnet restore .\\CVIS.Automation.Tests\\CVIS.Automation.Tests.csproj\n  - dotnet restore .\\CVIS.Playwright.NUnitCompat.Tests\\CVIS.Playwright.NUnitCompat.Tests.csproj\n  - dotnet build .\\CVIS.Automation.Tests\\CVIS.Automation.Tests.csproj --no-restore\n  - dotnet build .\\CVIS.Playwright.NUnitCompat.Tests\\CVIS.Playwright.NUnitCompat.Tests.csproj --no-restore\n\ntestSuites:\n  - dotnet test .\\CVIS.Automation.Tests\\CVIS.Automation.Tests.csproj --no-build --logger "trx;LogFileName=CVIS.Automation.Tests.trx" --results-directory ".\\TestResults\\NUnit\\CVIS.Automation.Tests" -- NUnit.TestOutputXml=.\\TestResults\\NUnitXml\\CVIS.Automation.Tests\n  - dotnet test .\\CVIS.Playwright.NUnitCompat.Tests\\CVIS.Playwright.NUnitCompat.Tests.csproj --no-build --logger "trx;LogFileName=CVIS.Playwright.NUnitCompat.Tests.trx" --results-directory ".\\TestResults\\NUnit\\CVIS.Playwright.NUnitCompat.Tests" -- NUnit.TestOutputXml=.\\TestResults\\NUnitXml\\CVIS.Playwright.NUnitCompat.Tests\n\npost:\n  - python .\\scripts\\build-cpn-report-from-nunitxml.py --nunit-xml-root .\\TestResults\\NUnitXml --output-root .\\TestResults\\CPN --framework-name "CVIS HyperExecute NUnit Run" --minimum-total 250\n\nreport: true\npartialReports:\n  type: nunit\n  location: .\\TestResults\\NUnitXml\n  frameworkName: nunit\n\nmergeArtifacts: true\nuploadArtefacts:\n  - name: cvis-authoritative-test-output\n    path:\n      - .\\TestResults\\NUnitXml\n      - .\\TestResults\\NUnit\n      - .\\TestResults\\CPN\n')
    write(ROOT / "README_AUTHORITATIVE_TEST_REPORTING.md", '# Authoritative HyperExecute / NUnit Reporting\n\n## The important rule\n\nThe report that counts for HyperExecute must come from **NUnit XML**, not the CPN lifecycle report.\n\nVisual Studio Test Explorer is showing NUnit-discovered tests. HyperExecute must be pointed at the same source:\n\n```text\nTestResults\\NUnitXml\n```\n\n## Why the old CPN report only showed 2 tests\n\nThe old CPN lifecycle report only recorded tests inheriting from:\n\n```csharp\nCVISPlaywrightTest\nCVISBrowserTest\nCVISContextTest\nCVISPageTest\nCVISApiTest\n```\n\nMost of the existing PolicyDrift tests are NUnit tests. They count in Visual Studio and they count in NUnit XML, but they do not all pass through the CPN lifecycle.\n\nSo the correct reporting path is:\n\n```text\ndotnet test\n  -> NUnit XML\n       -> HyperExecute parsed report\n       -> CPN full HTML report generated from NUnit XML\n```\n\n## Local authoritative run\n\nRun this from the solution root:\n\n```powershell\n.\\scripts\\run-all-nunit-reporting-local.ps1\n```\n\nExpected outputs:\n\n```text\nTestResults\\NUnitXml\nTestResults\\NUnit\nTestResults\\CPN\\cpn-report.html\nTestResults\\CPN\\cpn-report.json\nTestResults\\CPN\\cpn-report-summary.txt\n```\n\nOpen:\n\n```text\nTestResults\\CPN\\cpn-report.html\n```\n\nThat report is generated from NUnit XML and should line up with the real NUnit test count.\n\n## HyperExecute YAML\n\nUse:\n\n```text\nhyperexecute-authoritative-nunit-reporting.yaml\n```\n\nThe important section is:\n\n```yaml\nreport: true\npartialReports:\n  type: nunit\n  location: .\\TestResults\\NUnitXml\n  frameworkName: nunit\n```\n\nThat is what HyperExecute parses.\n\n## CPN report is artifact only\n\nThe CPN HTML report is uploaded as an artifact:\n\n```yaml\nuploadArtefacts:\n  - name: cvis-authoritative-test-output\n    path:\n      - .\\TestResults\\NUnitXml\n      - .\\TestResults\\NUnit\n      - .\\TestResults\\CPN\n```\n\n## Validation guard\n\nThe reporting script uses:\n\n```text\n--minimum-total 250\n```\n\nIf the NUnit XML contains fewer than 250 tests, the report generation fails. This prevents submitting a HyperExecute run that only captured 2 or 11 tests.\n')
    print("Added authoritative NUnit XML reporting path.")
    print("Run .\\scripts\\run-all-nunit-reporting-local.ps1 and open TestResults\\CPN\\cpn-report.html")

if __name__ == "__main__":
    main()
